import{respTasks,validRespAnswer,perMinute,recoveryData,extraOxygen,recoveryRoute,routeAdvance,lipidValid}from './resp-models.js?v=20261023-physicscomplete01';import{showResp}from './resp-visuals.js?v=20261023-physicscomplete01';export{showResp};
export function mountResp(l,p,root,{save,feedback,done}){let key=l.widget.slice(5),tasks=respTasks[key],w=p.widget;w.respTask??=0;w.respDrafts??={};w.respPassed??=[];let index=Math.min(tasks.length-1,w.respTask),t=tasks[index],v=w.respDrafts[index]??={state:0,answer:'',seen:[],step:0};v.seen??=[];let $=s=>root.querySelector(s),remount=()=>mountResp(l,p,root,{save,feedback,done});const field=(id,label,opts,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${opts.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`,number=(id,label,val)=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" type="number" step="any" id="${id}" value="${val??''}">`,near=(x,a)=>x!==''&&x!==undefined&&Number.isFinite(Number(x))&&Math.abs(Number(x)-a)<.001;let body='',draw,record,complete;
if(t.type==='compare'){body=field('respState','Compare the condition',t.states.map((s,i)=>[i,s[1]]),v.state)+field('respPrediction',t.prompt,t.choices.map((s,i)=>[i,s]),v.answer)+'<button class="secondary" id="revealResp">Reveal comparison →</button><p id="respReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.state;showResp(t.scene,{kind:t.scene,state:t.states[v.state][0],title:t.title,concealed:!r,stateLabel:t.states[v.state][1],result:r?t.results[v.state]:''});$('#respReadout').textContent=r?t.results[v.state]:'Predict before revealing.';};record=()=>{if(v.revealed!==v.state||!validRespAnswer(t,v.state,v.answer))return false;if(!v.seen.includes(v.state))v.seen.push(v.state);return true;};complete=()=>v.seen.length===t.states.length;}
else if(t.type==='sequence'){body='<p>Choose the next stage in the Higher recovery route. Explain transport separately from conversion.</p>'+field('respAction','Next route stage',[['muscle','Lactic acid accumulates in muscle'],['blood','Blood transports lactic acid'],['liver','Liver processes the lactic acid'],['glucose','Converted back into glucose']],v.respAction)+'<button class="secondary" id="advanceResp">Advance route →</button><p id="respReadout"></p>'+field('respReason','What does oxygen debt mean?',[['extra','Extra oxygen needed after exercise for accumulated lactic acid'],['all','All oxygen ever used at rest']],v.respReason);draw=()=>{showResp('recovery',{kind:'recovery',step:v.step,title:t.title,stateLabel:v.step+' /4 stages'});$('#respReadout').textContent='Recorded route: '+recoveryRoute.slice(0,v.step).join(' → ');};record=()=>v.step===4&&v.respReason==='extra';complete=record;}
else if(t.type==='lipid'){body='<p>Assemble one lipid using the specified building-block ratio.</p>'+number('glycerol','Glycerol molecules',v.glycerol)+number('fatty','Fatty acid molecules',v.fatty)+field('respReason','Energy for continual synthesis comes from…',[['respiration','Energy transferred by respiration'],['creation','Energy created from nothing']],v.respReason);draw=()=>showResp('lipid',{kind:'lipid',glycerol:v.glycerol??0,fatty:v.fatty??0,title:t.title,stateLabel:'Selected building blocks'});record=()=>lipidValid(v.glycerol,v.fatty)&&v.respReason==='respiration';complete=record;}
else{let isPulse=t.type==='pulse',cases=isPulse?[{count:36,seconds:30},{count:40,seconds:30}]:recoveryData;v.case??=0;let c=cases[v.case],expected=isPulse?perMinute(c.count,c.seconds):extraOxygen(c.rate,c.baseline,c.minutes);body='<p>'+(isPulse?'Original timed pulse readings: convert each to beats per minute.':'Each original recovery interval has the stated constant oxygen rate. Subtract resting use before multiplying by time.')+'</p>'+field('respCase','Choose the reading',cases.map((x,i)=>[i,isPulse?x.count+'beats in'+x.seconds+'s':'Use '+x.rate+'L/min; rest '+x.baseline+'L/min; '+x.minutes+'min']),v.case)+number('respNumber',isPulse?'Pulse rate / beats per minute':'Extra oxygen volume / L',v.respNumber)+field('respReason',isPulse?'Fair measurement approach':'Calculation rule',isPulse?[['matched','Same timed method; repeated comparable readings'],['different','Different unknown times and people']]:[['subtract','(Use rate − rest rate) × time'],['all','Use rate × time without subtracting rest']],v.respReason);draw=()=>showResp(isPulse?'exercise':'recovery-data',{kind:isPulse?'exercise':'recovery-data',title:t.title,stateLabel:isPulse?'Original exercise data':'Step-constant original oxygen data'});record=()=>{if(!near(v.respNumber,expected)||v.respReason!==(isPulse?'matched':'subtract'))return false;if(!v.seen.includes(v.case))v.seen.push(v.case);return true;};complete=()=>v.seen.length===cases.length;}
root.innerHTML='<p class="activity-count">'+(index+1)+' / '+tasks.length+' · '+t.title+'</p>'+body+'<p id="respEvidence"></p><div class="lab-actions"><button class="secondary" id="recordResp">Record reasoning</button><button class="secondary" id="nextResp">Next challenge →</button></div><p id="respProgress">'+w.respPassed.length+' / '+tasks.length+' complete</p>';draw();const evidence=()=>$('#respEvidence').textContent=t.type==='compare'?t.states.map((s,i)=>(v.seen.includes(i)?'✓ ':'○ ')+s[1]).join(' · '):v.seen.length?'Readings recorded: '+v.seen.map(i=>i+1).join(', '):'';evidence();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='respState'){v.state=Number(val||0);v.answer='';delete v.revealed;save();remount();return;}if(id==='respCase'){v.case=Number(val||0);v.respNumber='';save();remount();return;}if(id==='respPrediction')v.answer=val;else v[id]=val;save();if(t.type==='lipid')draw();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id]=e.target.value;save();if(t.type==='lipid')draw();};}
if($('#revealResp'))$('#revealResp').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.state;save();draw();feedback(validRespAnswer(t,v.state,v.answer)?'Prediction agrees. Record your reasoning.':t.why,!validRespAnswer(t,v.state,v.answer));};
if($('#advanceResp'))$('#advanceResp').onclick=()=>{let n=routeAdvance(v.step,v.respAction);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.respAction='';save();remount();};
$('#recordResp').onclick=()=>{if(!record()){feedback(t.why+' Check the selected evidence and reasoning.',true);return;}save();evidence();if(!complete()){feedback('Recorded. Compare the remaining conditions or readings.');return;}if(!w.respPassed.includes(index))w.respPassed.push(index);if(w.respPassed.length===tasks.length){p.widgetDone=true;done();}save();$('#respProgress').textContent=w.respPassed.length+' / '+tasks.length+' complete';feedback('Evidence and reasoning recorded.');};$('#nextResp').onclick=()=>{if(!w.respPassed.includes(index)){feedback('Complete this challenge first.',true);return;}w.respTask=(index+1)%tasks.length;save();remount();};}
